  ('2740f25b-588d-4e9e-950a-44de825b058d'::uuid),
  ('4f061e99-8077-42d8-91e2-5a4ba2c26d90'::uuid),
  ('51b9189c-f1a0-4733-955b-df1cb1967b8f'::uuid),
  ('534c5fef-4502-4e48-8bbf-676f93281eac'::uuid),
  ('6d69ab4e-c269-44e7-99de-648b266d6040'::uuid),
  ('89a1bb6e-f7dd-4437-a775-15128f926e53'::uuid),
  ('90653396-a0cc-4b59-ae26-945ea70649ef'::uuid),
  ('f21fc8b7-cc1d-496e-9739-9a28ea30b84c'::uuid)),
  reqs as (select to_regclass('public.statement_requirements') as oid),
  sets_t as (select to_regclass('public.statement_requirement_sets') as oid),
  dtc as (select pg_get_constraintdef(oid) as def from pg_constraint
           where conname = 'statement_requirements_document_type_known'
             and conrelid = (select oid from reqs)),
  checks as (

  select 100 as step, 'target database and executing role (INFO)' as check_name,
         'db=' || current_database() || ', current_user=' || current_user as actual,
         'the production project' as expected,
         'INFO' as verdict

  union all
  select 200, 'schema is post-007: both page columns are numeric(4,1)',
         coalesce((select string_agg(column_name || '=' || data_type || '('
                     || numeric_precision || ',' || numeric_scale || ')', ' '
                     order by column_name) from information_schema.columns
                    where table_schema = 'public'
                      and table_name = 'statement_requirements'
                      and column_name in ('min_pages','max_pages')), 'absent'),
         'both numeric(4,1)',
         case when (select count(*) from information_schema.columns
                     where table_schema = 'public'
                       and table_name = 'statement_requirements'
                       and column_name in ('min_pages','max_pages')
                       and data_type = 'numeric' and numeric_precision = 4
                       and numeric_scale = 1) = 2
              then 'PASS' else 'FAIL -- apply 007 first; the import stages 1.5 and would be refused' end

  union all
  select 201, 'schema is post-007: all nine document types accepted',
         (select (case when def like '%''personal-statement''%' then 1 else 0 end + case when def like '%''goal-statement''%' then 1 else 0 end + case when def like '%''diversity-statement''%' then 1 else 0 end + case when def like '%''writing-sample''%' then 1 else 0 end + case when def like '%''additional-response''%' then 1 else 0 end + case when def like '%''other''%' then 1 else 0 end + case when def like '%''statement-of-purpose''%' then 1 else 0 end + case when def like '%''autobiographical-essay''%' then 1 else 0 end + case when def like '%''supplemental-essay''%' then 1 else 0 end)::text from dtc) || ' of 9',
         '9 of 9',
         case when (select (case when def like '%''personal-statement''%' then 1 else 0 end + case when def like '%''goal-statement''%' then 1 else 0 end + case when def like '%''diversity-statement''%' then 1 else 0 end + case when def like '%''writing-sample''%' then 1 else 0 end + case when def like '%''additional-response''%' then 1 else 0 end + case when def like '%''other''%' then 1 else 0 end + case when def like '%''statement-of-purpose''%' then 1 else 0 end + case when def like '%''autobiographical-essay''%' then 1 else 0 end + case when def like '%''supplemental-essay''%' then 1 else 0 end) from dtc) = 9
              then 'PASS' else 'FAIL -- the payload carries types this constraint would refuse' end

  union all
  select 202, '006 signature: the eight register columns',
         (select count(*)::text from information_schema.columns
           where table_schema = 'public' and table_name = 'statement_requirements'
             and column_name in ('words_enforcement','words_stated_as',
                  'characters_enforcement','characters_stated_as','pages_enforcement',
                  'pages_stated_as','unenforced_length','unenforced_length_verbatim')) || ' of 8',
         '8 of 8',
         case when (select count(*) from information_schema.columns
                     where table_schema = 'public' and table_name = 'statement_requirements'
                       and column_name in ('words_enforcement','words_stated_as',
                            'characters_enforcement','characters_stated_as','pages_enforcement',
                            'pages_stated_as','unenforced_length','unenforced_length_verbatim')) = 8
              then 'PASS' else 'FAIL -- apply 006 first' end

  union all
  select 300, 'statement_requirement_sets is EMPTY  <<< the import does not merge',
         (select count(*)::text from public.statement_requirement_sets),
         '0',
         case when (select count(*) from public.statement_requirement_sets) = 0
              then 'PASS'
              else 'FAIL -- the catalog is not empty. STOP. Run the POSTCHECK and classify the state before considering any write; do not run the import to see what happens.' end

  union all
  select 301, 'statement_requirements is EMPTY',
         (select count(*)::text from public.statement_requirements),
         '0',
         case when (select count(*) from public.statement_requirements) = 0
              then 'PASS' else 'FAIL -- see step 300' end

  union all
  select 302, 'no row already carries one of the payload''s deterministic ids',
         (select count(*)::text from public.statement_requirement_sets
           where id in (select id from payload_sets)) || ' set(s), '
           || (select count(*)::text from public.statement_requirements
                where id in (select id from payload_docs)) || ' document(s)',
         '0 and 0',
         case when (select count(*) from public.statement_requirement_sets
                     where id in (select id from payload_sets)) = 0
               and (select count(*) from public.statement_requirements
                     where id in (select id from payload_docs)) = 0
              then 'PASS -- this exact payload has not been imported'
              else 'FAIL -- SOME OF THIS PAYLOAD IS ALREADY PRESENT. This is the partial-state signal. Do not import. Run the postcheck.' end

  union all
  select 400, 'every payload school_id exists in public.schools',
         (select count(*)::text from payload_schools p
           where not exists (select 1 from public.schools h where h.id = p.school_id))
           || ' missing of 63',
         '0 missing of 63',
         case when (select count(*) from payload_schools p
                     where not exists (select 1 from public.schools h
                                        where h.id = p.school_id)) = 0
              then 'PASS -- no school id is invented; all came from the approved reconciliation'
              else 'FAIL -- a referenced school is absent. The import will refuse.' end

  union all
  select 401, 'every payload school_id resolves to exactly one school row',
         (select count(*)::text from (select p.school_id from payload_schools p
            join public.schools h on h.id = p.school_id
           group by p.school_id having count(h.id) <> 1) q) || ' ambiguous',
         '0 ambiguous',
         case when (select count(*) from (select p.school_id from payload_schools p
                      join public.schools h on h.id = p.school_id
                     group by p.school_id having count(h.id) <> 1) q) = 0
              then 'PASS' else 'FAIL' end

  union all
  select 402, 'no school_id appears twice in the payload',
         (select count(*)::text from (select school_id from payload_schools
           group by school_id having count(*) > 1) q),
         '0',
         case when (select count(*) from (select school_id from payload_schools
                     group by school_id having count(*) > 1) q) = 0
              then 'PASS -- one set per school' else 'FAIL' end

  union all
  select 403, 'production school NAMES still match the reconciliation',
         (select count(*)::text from payload_schools p
            join public.schools h on h.id = p.school_id
           where btrim(h.name) <> btrim(p.expected_name)) || ' mismatch(es)',
         '0 mismatches',
         case when (select count(*) from payload_schools p
                      join public.schools h on h.id = p.school_id
                     where btrim(h.name) <> btrim(p.expected_name)) = 0
              then 'PASS -- every id still names the school it was approved against'
              else 'FAIL -- a school was RENAMED since the reconciliation was approved. The id may still be right, but a human must confirm it before importing.' end

  union all
  select 404, 'no HELD-BACK school id is in the payload',
         (select count(*)::text from payload_schools p
           where p.school_id in (select school_id from held_back)),
         '0',
         case when (select count(*) from payload_schools p
                     where p.school_id in (select school_id from held_back)) = 0
              then 'PASS -- the 10 held-back programmes with a production school are absent'
              else 'FAIL -- a held-back programme is in the payload' end

  union all
  select 500, 'payload cardinality',
         (select count(*)::text from payload_sets) || ' sets, '
           || (select count(*)::text from payload_docs) || ' documents',
         '63 sets, 80 documents',
         case when (select count(*) from payload_sets) = 63
               and (select count(*) from payload_docs) = 80
              then 'PASS' else 'FAIL -- the embedded payload is not the reviewed one' end

  union all
  select 600, 'grants unchanged: SELECT only to anon and authenticated',
         coalesce((select string_agg(table_name || '/' || grantee || '/' || privilege_type,
                                     '; ' order by table_name, grantee, privilege_type)
                     from information_schema.role_table_grants
                    where table_schema = 'public'
                      and table_name in ('statement_requirements','statement_requirement_sets')
                      and grantee in ('anon','authenticated','service_role')), 'none'),
         'SELECT only, on both tables',
         case when (select count(*) from information_schema.role_table_grants
                     where table_schema = 'public'
                       and table_name in ('statement_requirements','statement_requirement_sets')
                       and grantee in ('anon','authenticated','service_role')
                       and privilege_type <> 'SELECT') = 0
              then 'PASS -- the import needs no write grant; it runs as the table owner'
              else 'FAIL -- a browser role can write the catalog' end

  union all
  select 601, 'RLS still enabled on both catalog tables',
         (select string_agg(relname || '=' || relrowsecurity::text, '; ' order by relname)
            from pg_class where oid in ((select oid from reqs), (select oid from sets_t))),
         'both true',
         case when (select count(*) from pg_class
                     where oid in ((select oid from reqs), (select oid from sets_t))
                       and relrowsecurity) = 2
              then 'PASS' else 'FAIL' end

  union all
  select 602, 'policies still exactly the two 005 created',
         coalesce((select string_agg(tablename || '/' || policyname, '; ' order by tablename)
                     from pg_policies where schemaname = 'public'
                      and tablename in ('statement_requirements','statement_requirement_sets')), 'none'),
         'two SELECT policies',
         case when (select count(*) from pg_policies where schemaname = 'public'
                     and tablename in ('statement_requirements','statement_requirement_sets')) = 2
              then 'PASS' else 'FAIL' end

  union all
  select 700, 'neighbouring Statement Studio row counts (RECORD THESE)',
         'drafts=' || (select count(*)::text from public.statement_drafts)
           || ' prompts=' || (select count(*)::text from public.statement_prompts)
           || ' analyses=' || (select count(*)::text from public.statement_analyses),
         'record them',
         'INFO -- the import touches none of these. The postcheck compares.'

  union all
  select 800, 'rollout flags (NOT VISIBLE FROM SQL)',
         'check the deployment environment',
         'STATEMENT_REQUIREMENTS and STATEMENT_ANALYSIS_CACHE both off',
         'INFO -- the import activates nothing and every set lands is_active = false, so the catalog stays invisible even if a flag were on. Import and activation are separate approvals.'
)
select step, check_name, actual, expected, verdict
from checks
order by step;
